/** @CpfPermission을 Spring Security authority와 CPF Context 양쪽에 연결합니다. */
@Aspect public final class CpfPermissionAspect{private final CpfPermissionEvaluator evaluator;public CpfPermissionAspect(CpfPermissionEvaluator e){evaluator=e;}
 @Around("@annotation(com.cpf.security.api.annotation.CpfPermission) || @within(com.cpf.security.api.annotation.CpfPermission)") public Object around(ProceedingJoinPoint jp)throws Throwable{Method m=((MethodSignature)jp.getSignature()).getMethod();CpfPermission p=AnnotatedElementUtils.findMergedAnnotation(m,CpfPermission.class);if(p==null)p=AnnotatedElementUtils.findMergedAnnotation(m.getDeclaringClass(),CpfPermission.class);var ctx=CpfContexts.requireCurrent();var a=SecurityContextHolder.getContext().getAuthentication();var granted=a==null?java.util.Set.<String>of():a.getAuthorities().stream().map(x->x.getAuthority()).collect(Collectors.toUnmodifiableSet());evaluator.authorize(p,a!=null&&a.isAuthenticated(),granted,ctx);return jp.proceed();}}
